  this.ad1 = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f (\u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0430 \u0432\u0430\u043b\u044e\u0442\u0430, \u0432 \u044f\u043a\u0456\u0439 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f)";
  this.ab5 = "\u042f\u043a \u0432\u0441\u0442\u0443\u043f\u0430\u044e\u0442\u044c";
  this.aas = "\u0437\u0430 \u0432\u0430\u0448\u0438\u043c \u0440\u0456\u0448\u0435\u043d\u043d\u044f\u043c (\u043d\u0430\u0434\u0456\u0439\u043d\u0456\u0448\u0435)";
  this.abE = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u043d\u043e\u0432\u0430\u0447\u043a\u0430";
  this.abD = "\u0421\u0442\u0435\u043b\u044f \u043d\u043e\u0432\u0430\u0447\u043a\u0430";
  this.aaJ = "\u0413\u0440\u043e\u043c\u0430\u0434\u0443 \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043e";
  this.aaK = "\u0407\u0457 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u2014 \u0443 \u0446\u044c\u043e\u043c\u0443 \u0433\u0430\u043c\u0430\u043d\u0446\u0456. \u0417\u0430\u043f\u0440\u043e\u0448\u0443\u0439\u0442\u0435 \u043b\u044e\u0434\u0435\u0439 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f\u043c \u0456\u0437 \u0440\u043e\u0437\u0434\u0456\u043b\u0443 \u00ab\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438\u00bb \u0439 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u00ab\u0420\u0430\u0445\u0443\u043d\u043a\u0438\u00bb, \u0434\u0430\u043b\u0456 \u00ab\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0430\u0431\u043e \u0434\u043e\u0434\u0430\u0442\u0438 \u0449\u0435\u00bb.";
  this.ab9 = "\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438";
  this.aba = "\u041d\u0430\u0434\u0456\u0448\u043b\u0456\u0442\u044c \u0446\u0435 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u043e \u0445\u043e\u0447\u0435\u0442\u0435 \u0431\u0430\u0447\u0438\u0442\u0438 \u0432 \u0433\u0440\u043e\u043c\u0430\u0434\u0456. \u0412\u043e\u043d\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0454 \u0433\u0430\u043c\u0430\u043d\u0435\u0446\u044c \u043e\u0434\u0440\u0430\u0437\u0443 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456.";
  this.aaj = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0432\u0430\u0441";
  this.aaB = "\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0449\u0435 \u0440\u0430\u0437";
  this.ade = "\u0417\u0430\u0431\u0443\u0442\u0438 \u0446\u044e \u0437\u0430\u044f\u0432\u043a\u0443";
  this.acx = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.abK = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.aac = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.acv = "\u0412\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.aae = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.acw = "\u0412\u0456\u0434\u0445\u0438\u043b\u0435\u043d\u043e";
  this.abS = "\u041d\u0435 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
